import { test, expect } from '@playwright/test';

test.describe('Pinch-to-Zoom on Product Images', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/products');
  });

  test('should enable pinch-to-zoom on product images', async ({ page }) => {
    // Verify initial state: no zoom
    const image = page.getByRole('img', { name: /product image/i });
    await expect(image).toBeVisible();
    const zoomInButton = page.getByRole('button', { name: /zoom in/i });
    await expect(zoomInButton).toBeVisible();

    // Verify zoom in button is disabled by default
    await expect(zoomInButton).toBeDisabled();

    // Intercept API call to get product image
    await page.route('**/api/products/123/image', (route) => {
      route.continue();
    });

    // Pinch-to-zoom using touch events
    await page.evaluate(() => {
      const touchStart = new TouchEvent('touchstart', {
        target: document.querySelector('[data-testid="product-image"]'),
        touches: [new Touch({ clientX: 100, clientY: 100 })],
        identifier: 1,
        screenX: 100,
        screenY: 100,
      });
      const touchMove = new TouchEvent('touchmove', {
        target: document.querySelector('[data-testid="product-image"]'),
        touches: [new Touch({ clientX: 200, clientY: 200 })],
        identifier: 1,
        screenX: 200,
        screenY: 200,
      });
      const touchEnd = new TouchEvent('touchend', {
        target: document.querySelector('[data-testid="product-image"]'),
        touches: [new Touch({ clientX: 300, clientY: 300 })],
        identifier: 1,
        screenX: 300,
        screenY: 300,
      });

      document.dispatchEvent(touchStart);
      document.dispatchEvent(touchMove);
      document.dispatchEvent(touchEnd);
    });

    // Verify zoom in button is now enabled
    await expect(zoomInButton).not.toBeDisabled();

    // Verify zoom level is updated
    const zoomLevel = page.getByRole('heading', { name: /zoom level/i });
    await expect(zoomLevel).toBeVisible();
    await expect(zoomLevel).toContainText('100%');

    // Verify zoom in button is visible and clickable
    await expect(zoomInButton).toBeVisible();

    // Click zoom in button
    await zoomInButton.click();

    // Verify zoom level is increased
    await expect(zoomLevel).toContainText('200%');

    // Verify zoom out button is now enabled
    const zoomOutButton = page.getByRole('button', { name: /zoom out/i });
    await expect(zoomOutButton).toBeVisible();

    // Click zoom out button
    await zoomOutButton.click();

    // Verify zoom level is decreased
    await expect(zoomLevel).toContainText('100%');

    // Verify zoom in button is now disabled
    await expect(zoomInButton).toBeDisabled();
  });

  test('should handle pinch-to-zoom with multiple touch points', async ({ page }) => {
    // Verify initial state: no zoom
    const image = page.getByRole('img', { name: /product image/i });
    await expect(image).toBeVisible();
    const zoomInButton = page.getByRole('button', { name: /zoom in/i });
    await expect(zoomInButton).toBeVisible();
    await expect(zoomInButton).toBeDisabled();

    // Pinch-to-zoom using multiple touch points
    await page.evaluate(() => {
      const touch1 = new TouchEvent('touchstart', {
        target: document.querySelector('[data-testid="product-image"]'),
        touches: [new Touch({ clientX: 100, clientY: 100 })],
        identifier: 1,
        screenX: 100,
        screenY: 100,
      });
      const touch2 = new TouchEvent('touchmove', {
        target: document.querySelector('[data-testid="product-image"]'),
        touches: [new Touch({ clientX: 200, clientY: 200 })],
        identifier: 2,
        screenX: 200,
        screenY: 200,
      });
      const touch3 = new TouchEvent('touchend', {
        target: document.querySelector('[data-testid="product-image"]'),
        touches: [new Touch({ clientX: 300, clientY: 300 })],
        identifier: 3,
        screenX: 300,
        screenY: 300,
      });

      document.dispatchEvent(touch1);
      document.dispatchEvent(touch2);
      document.dispatchEvent(touch3);
    });

    // Verify zoom in button is now enabled
    await expect(zoomInButton).not.toBeDisabled();

    // Verify zoom level is updated
    const zoomLevel = page.getByRole('heading', { name: /zoom level/i });
    await expect(zoomLevel).toBeVisible();
    await expect(zoomLevel).toContainText('150%');

    // Verify zoom in button is visible and clickable
    await expect(zoomInButton).toBeVisible();

    // Click zoom in button
    await zoomInButton.click();

    // Verify zoom level is increased
    await expect(zoomLevel).toContainText('200%');

    // Verify zoom out button is now enabled
    const zoomOutButton = page.getByRole('button', { name: /zoom out/i });
    await expect(zoomOutButton).toBeVisible();

    // Click zoom out button
    await zoomOutButton.click();

    // Verify zoom level is decreased
    await expect(zoomLevel).toContainText('150%');

    // Verify zoom in button is now disabled
    await expect(zoomInButton).toBeDisabled();
  });
});
